---
{
  "schema_version": 1,
  "generated_by": "scripts/engine golden fixture derivation (frozen E1 hand computation)",
  "source": "data/tangerine/monthly_summary.csv and data/tangerine/loans.csv (sha256 verified against data/tangerine/SHA256SUMS)",
  "notes": [
    "Every sorted_cents array is the full account column in integer cents, sorted ascending, so each median step can be checked by hand.",
    "expected is asserted against scripts.engine.metrics.profile_metrics plus derive_flags and scripts.engine.shocks.runway, and against the shipped public/data/engine/profiles.json entry, by test_build_profiles.py.",
    "thin_history uses a threshold of 18 monthly rows: the dataset spans 72 months and its shortest account history is 12 rows, so a 6 row rule would never fire on real data (see docs/decisions.md Phase E1).",
    "A pensioner with a running status C loan cannot exist in this data: all 740 accounts with pension_in above zero have no row in loans.csv, and all 682 loan accounts have pension_in equal to zero. The pensioner fixture 98952 therefore has no loan, and the running loan status C case is covered by fixture 68257.",
    "Runway coverage across the five fixtures: finite wi
---
import type { RunwayState } from './shocks'

const CAD_FORMAT = new Intl.NumberFormat('en-CA', {
  style: 'currency',
  currency: 'CAD',
})

/**
 * Format integer CAD cents as a dollar string (for example $1,234.56).
 * Negative cents keep their numeric minus in front of the symbol
 * (for example -$1,234.50), which is the one allowed dash in shipped
 * strings because it is a formatted number, not prose. Non finite input
 * reads n/a instead of printing NaN on a card.
 */
export function formatCents(cents: number): string {
  if (!Number.isFinite(cents)) {
    return 'n/a'
  }
  return CAD_FORMAT.format(cents / 100)
}

/**
 * Format tenths of a month for the runway readouts: 98 reads 9.8 months,
 * the no_shortfall cap reads 120+ months, and a depleted buffer reads
 * 0.0 months. The state wins over the number so the two special states
 * can never print as an ordinary figure.
 */
export function formatDeciMonths(deciMonths: number, state: RunwayState): string {
  if (state === 'no_shortfall') {
    return '120+ months'
  }
  if (state === 'buffer_depleted') {
    return '0.0 months'
  }
  if (!Number.isFinite(deciMonths)) {
    return 'n/a months'
  }
  return `${(deciMonths / 10).toFixed(1)} months`
}

/** Format an m/s budget for the HUD (one decimal, for example 1641.5 m/s). */
export function formatMetersPerSecond(value: number): string {
  return `${value.toFixed(1)} m/s`
}

