/* ==========================================================================
   Phase E3 weather surfaces, the --wx- token namespace
   (docs/research.md palette table, "New tokens live in a --wx- namespace
   next to --rp and --rv so the report and Money River files never change").

   The seven state tokens, one per weather state in canonical order:

     wx-clear     #56B4E9   sky blue (Okabe-Ito), calm and no shortfall
     wx-cloudy    #46617c   cloud slate, long runway with a spending gap
     wx-overcast  #2f4257   deep slate, the darker sibling of cloudy
     wx-rain      #2f7f7c   water lit, spending driven 3.0 to 11.9 months
     wx-drought   #d97b3f   drought orange, income covers 65 percent or less
     wx-storm     #ff6a4d   storm vermillion, runway under 3.0 months
     wx-flood     #10333f   water deep, buffer depleted or runway at 0.0

   Plus the two grounds every surface sits on: wx-grounds #070c18 (the
   archival navy, same value as --rp-void but read from its own token so
   this file never depends on --rp-) and wx-parchment #e9e0c9 for text.

   Soft tints (each state color at 26 percent over wx-grounds) carry every
   printed label, so measured contrast for parchment text stays above
   WCAG AA on all seven cells (worst case 9.3 to 1 on wx-clear-soft).
   Solid state colors are used for tile fills, swatches, and rules only,
   where no small text sits on them.

   Motion in this file is gated behind prefers-reduced-motion:
   no-preference, matching src/index.css, which also zeroes animation
   durations globally under prefers-reduced-motion: reduce.
   ========================================================================== */

:root {
  /* The seven state colors. */
  --wx-clear: #56b4e9;
  --wx-cloudy: #46617c;
  --wx-overcast: #2f4257;
  --wx-rain: #2f7f7c;
  --wx-drought: #d97b3f;
  --wx-storm: #ff6a4d;
  --wx-flood: #10333f;

  /* Grounds and text. */
  --wx-grounds: #070c18;
  --wx-parchment: #e9e0c9;
  --wx-rule: rgba(233, 224, 201, 0.24);
  --wx-text-dim: rgba(233, 224, 201, 0.74);
  --wx-text-faint: rgba(233, 224, 201, 0.54);

  /* Soft tints for any surface that prints text on a state color. */
  --wx-clear-soft: #1c384e;
  --wx-cloudy-soft: #172232;
  --wx-overcast-soft: #111a28;
  --wx-rain-soft: #112a32;
  --wx-drought-soft: #3e2922;
  --wx-storm-soft: #482426;
  --wx-flood-soft: #091622;

  /* Utility, deliberately local so nothing here reaches into --rp-. */
  --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
    "Liberation Mono", monospace;
  --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --wx-radius: 4px;
}

/* ==========================================================================
   Forecast strip: 12 month tiles, one per weather state
   ========================================================================== */

.wx-strip {
  display: block;
  width: 100%;
}

.wx-strip__svg {
  display: block;
  width: 100%;
  height: auto;
}

.wx-tile {
  fill: var(--wx-rule);
}

.wx-tile--clear {
  fill: var(--wx-clear);
}

.wx-tile--cloudy {
  fill: var(--wx-cloudy);
}

.wx-tile--overcast {
  fill: var(--wx-overcast);
}

.wx-tile--rain {
  fill: var(--wx-rain);
}

.wx-tile--drought {
  fill: var(--wx-drought);
}

.wx-tile--storm {
  fill: var(--wx-storm);
}

.wx-tile--flood {
  fill: var(--wx-flood);
}

.wx-strip__glyph {
  font-family: var(--wx-font-body);
  font-size: 15px;
}

.wx-strip__month {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 9.5px;
  letter-spacing: 0.06em;
}

.wx-strip__empty {
  fill: var(--wx-parchment);
  font-family: var(--wx-font-display);
  font-size: 11px;
}

.wx-strip__placeholder {
  fill: none;
  stroke: var(--wx-rule);
  stroke-dasharray: 4 4;
}

/* ==========================================================================
   Condition bands: the sky legend with the printed threshold sentence
   ========================================================================== */

.wx-bands {
  display: flex;
  flex-direction: column;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.wx-band {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 8px 12px;
  background: var(--wx-clear-soft);
  border: 1px solid var(--wx-rule);
  border-left-width: 6px;
  border-radius: var(--wx-radius);
}

.wx-band--clear {
  background: var(--wx-clear-soft);
  border-left-color: var(--wx-clear);
}

.wx-band--cloudy {
  background: var(--wx-cloudy-soft);
  border-left-color: var(--wx-cloudy);
}

.wx-band--overcast {
  background: var(--wx-overcast-soft);
  border-left-color: var(--wx-overcast);
}

.wx-band--rain {
  background: var(--wx-rain-soft);
  border-left-color: var(--wx-rain);
}

.wx-band--drought {
  background: var(--wx-drought-soft);
  border-left-color: var(--wx-drought);
}

.wx-band--storm {
  background: var(--wx-storm-soft);
  border-left-color: var(--wx-storm);
}

.wx-band--flood {
  background: var(--wx-flood-soft);
  border-left-color: var(--wx-flood);
}

.wx-band--active {
  box-shadow: inset 0 0 0 2px var(--wx-parchment);
}

.wx-band__glyph {
  font-size: 1rem;
  color: var(--wx-parchment);
}

.wx-band__body {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  min-width: 0;
}

.wx-band__label {
  font-family: var(--wx-font-display);
  font-size: 0.8125rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--wx-parchment);
}

.wx-band__threshold {
  font-family: var(--wx-font-body);
  font-size: 0.8125rem;
  color: var(--wx-text-dim);
}

/* ==========================================================================
   EI cliff overlay: a marker line that sits over the forecast strip.
   The wiring view wraps the strip and this overlay in .wx-cliff-wrap,
   which is the positioning context (ForecastStrip lays monthCount equal
   width tiles across the full width, so a left percentage lands on the
   tile boundary the line claims).
   ========================================================================== */

.wx-cliff-wrap {
  position: relative;
}

.wx-cliff {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 0;
  border-left: 2px dashed var(--wx-storm);
  pointer-events: none;
  z-index: 2;
}

.wx-cliff__label {
  position: absolute;
  top: 3px;
  left: 0;
  white-space: nowrap;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--wx-storm);
  color: var(--wx-grounds);
  font-family: var(--wx-font-display);
  font-size: 0.625rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* ==========================================================================
   Storm Atlas: seven count cells, state tinted, text on soft tints
   ========================================================================== */

.wx-atlas {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.wx-atlas__headline {
  margin: 0;
  font-family: var(--wx-font-display);
  font-size: 1.125rem;
  line-height: 1.45;
  letter-spacing: 0.02em;
  color: var(--wx-parchment);
}

.wx-atlas__note {
  margin: 0;
  font-family: var(--wx-font-body);
  font-size: 0.8125rem;
  color: var(--wx-text-faint);
}

.wx-atlas__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
  gap: 10px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.wx-atlas__cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 44px;
  padding: 10px 12px;
  text-align: left;
  font-family: var(--wx-font-body);
  color: var(--wx-parchment);
  background: var(--wx-clear-soft);
  border: 1px solid var(--wx-rule);
  border-top-width: 5px;
  border-radius: var(--wx-radius);
}

button.wx-atlas__cell {
  cursor: pointer;
}

.wx-atlas__cell--clear {
  background: var(--wx-clear-soft);
  border-top-color: var(--wx-clear);
}

.wx-atlas__cell--cloudy {
  background: var(--wx-cloudy-soft);
  border-top-color: var(--wx-cloudy);
}

.wx-atlas__cell--overcast {
  background: var(--wx-overcast-soft);
  border-top-color: var(--wx-overcast);
}

.wx-atlas__cell--rain {
  background: var(--wx-rain-soft);
  border-top-color: var(--wx-rain);
}

.wx-atlas__cell--drought {
  background: var(--wx-drought-soft);
  border-top-color: var(--wx-drought);
}

.wx-atlas__cell--storm {
  background: var(--wx-storm-soft);
  border-top-color: var(--wx-storm);
}

.wx-atlas__cell--flood {
  background: var(--wx-flood-soft);
  border-top-color: var(--wx-flood);
}

.wx-atlas__cell--selected {
  box-shadow: inset 0 0 0 2px var(--wx-parchment);
}

.wx-atlas__state {
  font-family: var(--wx-font-display);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--wx-text-dim);
}

.wx-atlas__count {
  font-family: var(--wx-font-display);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.wx-atlas__percent {
  font-family: var(--wx-font-body);
  font-size: 0.75rem;
  color: var(--wx-text-dim);
  font-variant-numeric: tabular-nums;
}

/* ==========================================================================
   Motion: strip tiles settle in, the cliff line draws down. Only when
   motion is welcome; the global prefers-reduced-motion: reduce block in
   src/index.css zeroes every animation duration as well.
   ========================================================================== */

@media (prefers-reduced-motion: no-preference) {
  .wx-strip__tile {
    animation: wx-fade 380ms ease-out backwards;
    animation-delay: var(--wx-delay, 0ms);
  }

  .wx-cliff {
    animation: wx-fade 480ms ease-out backwards;
  }
}

@keyframes wx-fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

