import { createElement } from 'react'
import { renderToString } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import ForecastStrip, { FORECAST_MONTH_COUNT, type ForecastMonth } from './ForecastStrip'

/**
 * The forecast strip must render in every wiring state: no props at all
 * (the placeholder), and a full 12 month array colored by state. Server
 * rendering runs no effects, so these assert the markup contract the E3
 * view mounts against.
 */

function months(): ForecastMonth[] {
  const states = [
    'clear',
    'cloudy',
    'overcast',
    'rain',
    'drought',
    'storm',
    'flood',
    'clear',
    'rain',
    'storm',
    'cloudy',
    'clear',
  ] as const
  return states.map((state, index) => ({
    month: `2026-${String(index + 1).padStart(2, '0')}`,
    state,
    runwayDeciMonths: 120 - index * 9,
  }))
}

describe('ForecastStrip', () => {
  it('renders a labelled placeholder with no props at all', () => {
    const html = renderToString(createElement(ForecastStrip))
    expect(html).toContain('forecast not wired yet')
    expect(html).toContain('no forecast wired yet')
    expect(html).toContain('role="img"')
  })

  it('renders a placeholder for an empty months array', () => {
    const html = renderToString(createElement(ForecastStrip, { months: [] }))
    expect(html).toContain('forecast not wired yet')
  })

  it('draws one state colored tile per month with the month label', () => {
    const html = renderToString(createElement(ForecastStrip, { months: months() }))
    expect(html).not.toContain('forecast not wired yet')
    for (const state of ['clear', 'cloudy', 'overcast', 'rain', 'drought', 'storm', 'flood']) {
      expect(html).toContain(`wx-tile--${state}`)
    }
    expect(html).toContain('wx-strip__tile')
    // Month labels are the MM tail of each YYYY-MM label.
    expect(html).toContain('>01<')
    expect(html).toContain('>12<')
    expect(html).toContain('Forecast strip, 12 months')
    expect(html).toContain('runway 12.0 months')
  })

  it('honours a caller aria label and the exported tile count', () => {
    expect(FORECAST_MONTH_COUNT).toBe(12)
    const html = renderToString(
      createElement(ForecastStrip, { months: months(), ariaLabel: 'Judge forecast' }),
    )
    expect(html).toContain('Judge forecast')
  })

  it('renders one tile per provided month, not a fixed twelve', () => {
    const three = months().slice(0, 3)
    const html = renderToString(createElement(ForecastStrip, { months: three }))
    const tiles = html.split('wx-strip__tile').length - 1
    expect(tiles).toBe(3)
    expect(html).toContain('Forecast strip, 3 months')
  })
})

import { createElement } from 'react'
import { renderToString } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import ForecastStrip, { FORECAST_MONTH_COUNT, type ForecastMonth } from './ForecastStrip'

/**
 * The forecast strip must render in every wiring state: no props at all
 * (the placeholder), and a full 12 month array colored by state. Server
 * rendering runs no effects, so these assert the markup contract the E3
 * view mounts against.
 */

function months(): ForecastMonth[] {
  const states = [
    'clear',
    'cloudy',
    'overcast',
    'rain',
    'drought',
    'storm',
    'flood',
    'clear',
    'rain',
    'storm',
    'cloudy',
    'clear',
  ] as const
  return states.map((state, index) => ({
    month: `2026-${String(index + 1).padStart(2, '0')}`,
    state,
    runwayDeciMonths: 120 - index * 9,
  }))
}

describe('ForecastStrip', () => {
  it('renders a labelled placeholder with no props at all', () => {
    const html = renderToString(createElement(ForecastStrip))
    expect(html).toContain('forecast not wired yet')
    expect(html).toContain('no forecast wired yet')
    expect(html).toContain('role="img"')
  })

  it('renders a placeholder for an empty months array', () => {
    const html = renderToString(createElement(ForecastStrip, { months: [] }))
    expect(html).toContain('forecast not wired yet')
  })

  it('draws one state colored tile per month with the month label', () => {
    const html = renderToString(createElement(ForecastStrip, { months: months() }))
    expect(html).not.toContain('forecast not wired yet')
    for (const state of ['clear', 'cloudy', 'overcast', 'rain', 'drought', 'storm', 'flood']) {
      expect(html).toContain(`wx-tile--${state}`)
    }
    expect(html).toContain('wx-strip__tile')
    // Month labels are the MM tail of each YYYY-MM label.
    expect(html).toContain('>01<')
    expect(html).toContain('>12<')
    expect(html).toContain('Forecast strip, 12 months')
    expect(html).toContain('runway 12.0 months')
  })

  it('honours a caller aria label and the exported tile count', () => {
    expect(FORECAST_MONTH_COUNT).toBe(12)
    const html = renderToString(
      createElement(ForecastStrip, { months: months(), ariaLabel: 'Judge forecast' }),
    )
    expect(html).toContain('Judge forecast')
  })

  it('renders one tile per provided month, not a fixed twelve', () => {
    const three = months().slice(0, 3)
    const html = renderToString(createElement(ForecastStrip, { months: three }))
    const tiles = html.split('wx-strip__tile').length - 1
    expect(tiles).toBe(3)
    expect(html).toContain('Forecast strip, 3 months')
  })
})

import './weather.css'
import { SEVERITY_ORDER, WEATHER_META, type WeatherState } from '../../lib/weatherState'

/**
 * The condition bands: the sky legend that prints all seven states with
 * their glyph, label, and threshold sentence. This is the "each state
 * also carries a unique icon silhouette and a printed label" rule from
 * docs/research.md made concrete, so no surface ever distinguishes
 * states by color alone.
 *
 * Bands read the solid state color as the left rule and the soft tint as
 * the background, which keeps the printed threshold sentence above WCAG
 * AA on every band (see the contrast note in weather.css). The active
 * state gets an inset parchment outline and aria-current, which is how
 * the console marks the account's current sky. The scaffold renders for
 * empty props with the full severity ladder, so it is safe to mount
 * before any account is loaded.
 */

export interface WeatherBandsProps {
  /** States to show, in caller order. Defaults to severity, severe first. */
  states?: readonly WeatherState[] | null
  /** The account's current state, highlighted in the ladder. */
  activeState?: WeatherState | null
}

export default function WeatherBands(props: WeatherBandsProps) {
  const requested = props.states
  const states: readonly WeatherState[] =
    requested && requested.length > 0 ? requested : SEVERITY_ORDER
  const active = props.activeState ?? null

  return (
    <ul className="wx-bands" aria-label="Weather condition bands">
      {states.map((state) => {
        const meta = WEATHER_META[state]
        const isActive = active === state
        return (
          <li
            key={state}
            className={`wx-band wx-band--${state}${isActive ? ' wx-band--active' : ''}`}
            aria-current={isActive ? 'true' : undefined}
          >
            <span className="wx-band__glyph" aria-hidden="true">
              {meta.glyph}
            </span>
            <span className="wx-band__body">
              <span className="wx-band__label">{meta.label}</span>
              <span className="wx-band__threshold">{meta.threshold}</span>
            </span>
          </li>
        )
      })}
    </ul>
  )
}

