import { createElement } from 'react'
import { renderToString } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import WeatherBands from './WeatherBands'
import { SEVERITY_ORDER, WEATHER_META, WEATHER_STATES } from '../../lib/weatherState'

/**
 * The condition bands must print all seven states with glyph, label,
 * and threshold sentence for empty props, and mark the active state
 * with aria-current so the console can point at the account's sky.
 */

describe('WeatherBands', () => {
  it('renders the full severity ladder with no props', () => {
    const html = renderToString(createElement(WeatherBands))
    expect(html).toContain('aria-label="Weather condition bands"')
    for (const state of WEATHER_STATES) {
      expect(html).toContain(`wx-band--${state}`)
      expect(html).toContain(WEATHER_META[state].label)
      expect(html).toContain(WEATHER_META[state].glyph)
      expect(html).toContain(WEATHER_META[state].threshold)
    }
    expect(html).not.toContain('aria-current')
  })

  it('renders nothing but the ladder for an empty states array', () => {
    const html = renderToString(createElement(WeatherBands, { states: [] }))
    const bands = html.split('wx-band wx-band--').length - 1
    expect(bands).toBe(WEATHER_STATES.length)
  })

  it('marks the active state with aria-current and the active class', () => {
    const html = renderToString(createElement(WeatherBands, { activeState: 'storm' }))
    expect(html).toContain('wx-band wx-band--storm wx-band--active')
    expect(html).toContain('aria-current="true"')
    // Only one band is active.
    expect(html.split('wx-band--active').length - 1).toBe(1)
  })

  it('honours a caller order and keeps severity order as the default', () => {
    expect([...SEVERITY_ORDER][0]).toBe('flood')
    const subset = ['rain', 'clear'] as const
    const html = renderToString(createElement(WeatherBands, { states: subset }))
    expect(html.split('wx-band wx-band--').length - 1).toBe(2)
    expect(html).toContain('wx-band--rain')
    expect(html).toContain('wx-band--clear')
    expect(html).not.toContain('wx-band--flood')
  })

  it('renders safely for an unknown active state', () => {
    const html = renderToString(
      createElement(WeatherBands, { activeState: 'hail' as never }),
    )
    expect(html).not.toContain('aria-current')
    expect(html.split('wx-band wx-band--').length - 1).toBe(WEATHER_STATES.length)
  })
})

import { createElement } from 'react'
import { renderToString } from 'react-dom/server'
import { describe, expect, it } from 'vitest'
import EiCliffOverlay, { EI_CLIFF_INDEX, EI_CLIFF_LABEL } from './EiCliffOverlay'

/**
 * The EI cliff marker is presentational: it draws at cliffIndex /
 * monthCount, defaults to the standard 6 month EI twist, and renders
 * nothing for missing or out of range indices so a mount can never draw
 * a stray marker over a forecast that has no EI twist applied.
 */

describe('EiCliffOverlay', () => {
  it('defaults to the standard EI twist marker at month 7 of 12', () => {
    expect(EI_CLIFF_INDEX).toBe(6)
    const html = renderToString(createElement(EiCliffOverlay))
    expect(html).toContain('wx-cliff')
    expect(html).toContain(EI_CLIFF_LABEL)
    // 6 of 12 tiles is the halfway line, 50 percent from the left.
    expect(html).toContain('left: 50%')
    expect(html).toContain('month 7 of 12')
  })

  it('renders nothing when the cliff is hidden', () => {
    expect(renderToString(createElement(EiCliffOverlay, { cliffIndex: null }))).not.toContain(
      'wx-cliff',
    )
    expect(renderToString(createElement(EiCliffOverlay, { cliffIndex: undefined }))).toContain(
      'wx-cliff',
    )
  })

  it('renders nothing for out of range or invalid indices', () => {
    expect(renderToString(createElement(EiCliffOverlay, { cliffIndex: -1 }))).not.toContain(
      'wx-cliff',
    )
    expect(renderToString(createElement(EiCliffOverlay, { cliffIndex: 12 }))).not.toContain(
      'wx-cliff',
    )
    expect(
      renderToString(createElement(EiCliffOverlay, { cliffIndex: Number.NaN })),
    ).not.toContain('wx-cliff')
    expect(
      renderToString(createElement(EiCliffOverlay, { cliffIndex: Number.POSITIVE_INFINITY })),
    ).not.toContain('wx-cliff')
  })

  it('positions against the caller month count and keeps the label inside', () => {
    const html = renderToString(
      createElement(EiCliffOverlay, { cliffIndex: 2, monthCount: 6 }),
    )
    // 2 of 6 tiles is a third across.
    expect(html).toContain('left: 33.333333333333336%')
    expect(html).toContain('month 3 of 6')
    expect(html).toContain('translateX(-50%)')

    const edge = renderToString(createElement(EiCliffOverlay, { cliffIndex: 0, monthCount: 12 }))
    expect(edge).toContain('translateX(0)')
    expect(edge).toContain('left: 0%')
  })

  it('accepts a caller label and an invalid month count fallback', () => {
    const html = renderToString(
      createElement(EiCliffOverlay, { cliffIndex: 3, monthCount: Number.NaN, label: 'EI ends' }),
    )
    expect(html).toContain('EI ends')
    expect(html).toContain('month 4 of 12')
  })
})

